css:
ul li{
    margin-bottom:0px;
    padding-bottom:0px;
}
.holiday-row {
    background-color: #DFF0D8; /* Light green background */
    color: #3C763D; /* Dark green text */
    font-style: italic;
}

body {
font-family: 'Times New Roman', Times, serif;
margin:0px;
padding:0px;
}
.logo_png{
    display:flex;
}
.log_sheet{
    font-size:24px;
    white-space: nowrap;
    font-family: 'Times New Roman', Times, serif;
}
.details-table {
    width: 100%;
    margin-bottom: 20px;
    border-collapse: collapse;
}

.details-table td {
    padding: 0px !important;
    vertical-align: top;
    font-family: 'Times New Roman', Times, serif;
}

.details-table td:nth-child(3) {
    white-space: nowrap;
}

.log-table-container {
    width: 100%;
    overflow-x: auto;
}

table {
    width: 100%;
    border-collapse: collapse;
    font-size: 14px;
}

table, th, td {
    border: 1.5px solid black;
}

th, td {
    padding: 5px;
    text-align: left;
    vertical-align: middle;
}

.log_table_th{
    background-color: #00B8AE;
    color: black;
    text-align: center;
}

.right {
    text-align: right;
}
.print-format th{
    color:black;
}
.cl{
    color:#00EA48;
    font-size:22px;
    font-family: 'Times New Roman', Times, serif;
}
.ryss{
    color:#FF0000;
    font-size:18.5px;
    font-family: 'Times New Roman', Times, serif;
}
.print-format td, .print-format th{
   padding:2px !important;
}
body:last-child .print-format td img{
   /*width:22% !important;*/
   height:75px;
}
.center{
   text-align:center;
}
.cl_1{
   font-size:14px;
}
